-- Thread 1 (sort 347): the-day-of-vindication-of-the-righteous-and-the-judgment-of-the-nations-in-wisdom-of-solomon
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-day-of-vindication-of-the-righteous-and-the-judgment-of-the-nations-in-wisdom-of-solomon',
       'The day of vindication of the righteous and the judgment of the nations — Wisdom of Solomon 3 and 5''s reversal-architecture for the sheep-and-goats-judgment',
       'Matt 25:31-46''s sheep-and-goats-judgment-at-the-throne-of-his-glory + the reversal-architecture-of-the-righteous-vindicated-and-the-ungodly-confessing — read against the wisdom-stream''s direct articulation of the day-of-vindication-of-the-righteous + the gathered-remnant-judging-the-nations + the great-boldness-of-the-righteous-before-the-face-of-such-as-have-afflicted-him substance in Wisdom of Solomon 3 and 5. Four moves: Wisdom of Solomon 3:7 names the wisdom-stream verbal-anchor for the day-of-visitation when the righteous shine — the same architecture the apostle-Sha''ul (Paul) walks at 1 Thessalonians 4:13-17 and the prophet-Daniel walked at Daniel 12:3''s *they that be wise shall shine as the brightness of the firmament*; Wisdom of Solomon 3:8 names THE direct verbal-anchor for the *they shall judge the nations, and have dominion over the people* — the gathered-remnant of the seed-of-promise participates in the judgment-of-the-nations at Matt 25:32, the same architecture Daniel 7:22, 27 walks (*the saints possessed the kingdom* + *the kingdom and dominion ... shall be given to the people of the saints of the most High*); Wisdom of Solomon 5:5 names the children-of-Yahuah-substance + the lot-among-the-saints substance — the inheritance-prepared-from-the-foundation-of-the-world the King declares at Matt 25:34, in continuity with Red Line #11''s names-written-in-the-Lamb''s-book-from-the-foundation-of-the-world architecture per Revelation 13:8, 17:8; Wisdom of Solomon 5:1 names THE direct verbal-anchor for the reversal-architecture (*then shall the righteous man stand in great boldness before the face of such as have afflicted him*) — the day the wisdom-stream prefigured is the day Matt 25:41 enacts, with the ungodly confessing at vv.42-44 the same way Wisdom of Solomon 5:2-6 had named (*they shall be troubled with terrible fear* + *therefore have we erred from the way of truth*). The framework reads the cluster as the wisdom-stream''s direct corroboration of the reversal-and-vindication-architecture the King-of-Yashar''el (Israel) walks-out at the sheep-and-goats-judgment. The substantial-everlasting-fire of v.41 was-substantively-prepared-FOR-the-devil-and-his-angels per Jude 6-7 + 2 Peter 2:4 + Revelation 20:10 + 20:14-15, NOT for the surviving-nations categorically; the surviving-nations align-themselves-into-the-Watcher-architecture by their reception-or-rejection of the King''s-brethren during the tribulation per Red Line #11.',
       sv.verse_id, ev.verse_id, 'complete_study', 347
  FROM _s156_xref_lookup sv, _s156_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 25 AND sv.verse_number = 31
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 25 AND ev.verse_number = 46
ON CONFLICT (slug) DO NOTHING;

-- Thread 2 (sort 348): the-diligent-stewardship-versus-the-slothful-servant-in-sirach
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-diligent-stewardship-versus-the-slothful-servant-in-sirach',
       'The diligent stewardship versus the slothful servant — Sirach''s wisdom-stream articulation of the trade-the-deposit substance for the parable of the talents',
       'Matt 25:14-30''s parable-of-the-talents — the substantial-substance of the present-age-stewardship between the Ascension and the second-coming + the two-faithful-servants both rewarded equally on faithfulness (NOT on quantity) + the unprofitable-servant cast-into-outer-darkness for-the-substantial-failure-of-stewardship — read against the wisdom-stream''s direct articulation of the diligent-labour-versus-the-slothful substance in Sirach (Ecclesiasticus). Four moves: Sirach 11:21 names the trust-and-abide-in-your-labour substance (*Marvel not at the works of sinners; but trust in Yahuah (God), and abide in your labour*) — the substantial-substance the faithful-servants walk-out at the doubling of the talents; Sirach 22:1 names THE direct verbal-anchor for the slothful-substance (*A slothful man is compared to a filthy stone*) — the operative-form of the substantial-failure-of-action the King-of-Yashar''el (Israel) walks-against at the unprofitable-servant; Sirach 33:28 names the master''s set-him-to-work substance with the substantial-consequences-for-the-failure-of-the-work; Sirach 51:30 names THE direct verbal-anchor for the work-your-work-betimes + the reward-in-his-time substance (*Work your work betimes, and in his time he will give you your reward*) — the substantial-reward the substantial-faithful-servants walk-into is the substantial-millennial-reign-stewardship per Revelation 2:26-27, 3:21, 5:10, 20:4-6 + the twelve-thrones at Matt 19:28 + the marriage-of-the-Lamb at Revelation 19:7-9. The framework reads the cluster as the wisdom-stream''s direct corroboration of the post-harvest-sifting per Red Line #11''s architecture — the unprofitable-servant has-been-given-the-talent (the substantial-grace) + has-been-named-as-a-servant (the substantial-relationship) + has-been-cast-into-outer-darkness for-the-substantial-failure-of-stewardship (the substantial-loss); the substantial-Reformation-eternal-security-substance is explicitly-ruled-out — the grace and the opportunity and the loss are all-three-substantial at-the-same-substance per Red Line #10''s sola-fide-grammar-corrected-by-the-completed-sentence framework. The wisdom-stream had named the architecture at the diligence-and-slothfulness-substance; the King-of-Yashar''el (Israel) walks the operative-form at the parable of the talents.',
       sv.verse_id, ev.verse_id, 'complete_study', 348
  FROM _s156_xref_lookup sv, _s156_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 25 AND sv.verse_number = 14
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 25 AND ev.verse_number = 30
ON CONFLICT (slug) DO NOTHING;

-- Thread 3 (sort 349): the-few-saved-many-lost-and-the-post-harvest-sifting-in-2-esdras
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-few-saved-many-lost-and-the-post-harvest-sifting-in-2-esdras',
       'The few saved, the many lost, and the post-harvest sifting — 2 Esdras (4 Ezra) 7 and 8''s articulation of the world-to-come-for-few + the work-shall-follow + the judgment-seat-of-the-Most-High',
       'Matt 25''s three sifting-parables — the ten-virgins shut-door at vv.10-13, the unprofitable-servant cast-into-outer-darkness at v.30, and the sheep-and-goats-judgment at vv.31-46 — read against the wisdom-stream''s direct articulation of the post-harvest-sifting per Red Line #11 in 2 Esdras (4 Ezra) 7 and 8. Four moves: 2 Esdras 8:1 names THE direct verbal-anchor for the world-to-come-for-few substance (*The most High has made this world for many, but the world to come for few*) — the substantial-architecture the shut-door at Matt 25:10 walks; 2 Esdras 8:3 names the direct articulation of the many-created-but-few-saved substance (*There be many created, but few shall be saved*) — the operative-substance of the substantial-many-called-but-few-chosen at Matt 22:14 and the substantial *I know you not* at Matt 25:12; 2 Esdras 7:35 names the work-shall-follow + the reward-shall-be-shewed substance — the substantial-substance the unprofitable-servant walks-into at Matt 25:30''s outer-darkness; 2 Esdras 7:33 names the Most-High-on-the-seat-of-judgment substance — the substantial-Davidic-Messianic-throne-of-his-glory the King-of-Yashar''el (Israel) sits-upon at Matt 25:32 + the gathering-of-all-nations + the separation-substance the prophet-Yo''el (Joel) walked at Joel 3:1-14 walks-into. The framework reads the cluster as the wisdom-stream''s direct corroboration of the post-harvest-sifting per Red Line #11 — the substantial-wheat-after-the-gathering is sifted-into-wheat-and-chaff; the substantial-foolish-virgins and the substantial-unprofitable-servant are wheat-that-did-not-bear-the-fruit-of-readiness-or-stewardship, NOT tares (the substantial-tares were burned at the harvest of Matt 13''s wheat-and-tares + Matt 24''s eagles-to-the-carcase). The substantial-name-can-be-substantively-blotted-out-of-the-Book-of-Life per Exodus 32:33 + Psalm 69:28 + Revelation 3:5 — the substantial-warning is-given-to-the-substantial-wheat, NOT to the substantial-tares. The wisdom-stream and the gospel cohere at the few-saved-many-lost + the work-shall-follow + the judgment-seat-of-the-Most-High architecture.',
       sv.verse_id, ev.verse_id, 'complete_study', 349
  FROM _s156_xref_lookup sv, _s156_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 25 AND sv.verse_number = 10
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 25 AND ev.verse_number = 32
