-- Thread 4 (sort 350): the-mercy-toward-the-poor-the-stranger-and-the-needy-as-the-criterion-of-righteousness-in-sirach-and-tobit
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-mercy-toward-the-poor-the-stranger-and-the-needy-as-the-criterion-of-righteousness-in-sirach-and-tobit',
       'The mercy toward the poor, the stranger, and the needy as the criterion of righteousness — Sirach and Tobit''s wisdom-stream witness to the sheep-and-goats criterion of mercy',
       'Matt 25:34-46''s sheep-and-goats criterion-of-mercy — the six-fold-substance (hungry-fed + thirsty-given-drink + stranger-taken-in + naked-clothed + sick-visited + prisoner-came-unto) + the substantial *Inasmuch as ye have done it unto one of the least of these my brethren, ye have done it unto me* + the reverse-six-fold-failure of the substantial-goats — read against the wisdom-stream''s direct articulation of the alms-and-mercy-toward-the-poor-and-stranger as the substance of righteousness in Sirach (Ecclesiasticus) and Tobit. Five moves: Tobit 4:16 names THE direct verbal-anchor for two of the six-fold-criterion (*Give of your bread to the hungry, and of your garments to them that are naked*) — the same substance the substantial Tanakh-prophets walked at Isaiah 58:6-10 + Job 31:16-22 + Deuteronomy 10:18-19 + Proverbs 19:17; Sirach 7:32 names the stretch-your-hand-to-the-poor substance, with 7:34 (*fail not to be with them that weep*) and 7:35 (*be not slow to visit the sick*) walking the same six-fold-substance the King-of-Yashar''el (Israel) walks at the criterion; Sirach 29:9 names the help-the-poor-for-the-commandment''s-sake substance — the substantial-doing-of-mercy-as-the-substantial-doing-of-the-commandment, NOT the substantial-categorical-charity-program-substance the inherited-Christian-collapse walks; Sirach 4:1 names the do-not-defraud-the-poor-and-make-not-the-needy-eyes-to-wait substance — the substantial-substance the reverse-six-fold-failure at Matt 25:42-44 walks-into; Tobit 4:7 names the give-alms + the-face-of-Yahuah-shall-not-be-turned-away substance — the substantial-doing-of-mercy walks the substantial-face-of-Yahuah-toward-the-doer. The framework reads the cluster as the wisdom-stream''s direct corroboration of the criterion-of-mercy substance — the substantial-substance is the substantial-mercy-toward-the-King''s-brethren-during-the-tribulation per Red Line #7''s Three-Categories-architecture; the substantial *my brethren* (Greek *tōn adelphōn mou*) is the gathered-remnant-of-the-twelve-tribes-of-Yashar''el (Israel)-substance the King-of-Yashar''el (Israel) walks-as-the-substantial-seed-of-promise per `kinship-redefinition-kingdom-family` thread at Matt 12:46-50, NOT the categorical-poor-and-vulnerable. The substantial-surviving-nations walk-into the millennial-reign-entry-substance through-the-substantial-mercy-toward-the-gathered-remnant-of-the-seed during the tribulation-and-gathering; the substantial-failure-of-mercy aligns-the-surviving-nations-into-the-Watcher-architecture per Red Line #11''s destination-reading.',
       sv.verse_id, ev.verse_id, 'complete_study', 350
  FROM _s156_xref_lookup sv, _s156_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 25 AND sv.verse_number = 34
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 25 AND ev.verse_number = 46
ON CONFLICT (slug) DO NOTHING;

-- Thread 5 (sort 351): the-judgment-of-the-kings-and-the-mighty-cast-down-in-1-enoch-parables
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-judgment-of-the-kings-and-the-mighty-cast-down-in-1-enoch-parables',
       'The judgment of the kings and the mighty cast down — 1 Enoch''s Parables on the Son of Adam raising-up-the-mighty-from-their-thrones at the throne of his glory',
       'Matt 25:31-46''s sheep-and-goats-judgment-of-the-nations — the Son-of-Adam-coming-in-his-glory + all-the-holy-angels-with-him + the throne-of-his-glory + all-nations-gathered-before-him + the separation-substance + the everlasting-fire-prepared-for-the-devil-and-his-angels — read against 1 Enoch''s Parables (chapters 46-63) on the Son-of-Adam-on-the-throne-of-his-glory raising-up-the-kings-and-mighty-from-their-seats + putting-them-down-from-their-thrones + the kings-and-mighty-seized-with-great-terror + the secrets-of-the-Most-High-revealed-to-the-Elect-One. Five moves: 1 Enoch 62:5 names the wisdom-stream context for the throne-of-his-glory + the secrets-of-the-Most-High substance + the books-of-the-living-opened-before-him — the substantial-architecture the sheep-and-goats opening at Matt 25:31 walks-into directly; 1 Enoch 62:3 names the substantial-angelic-host-summoned-with-the-Elect-One substance — the substantial-substance Matt 25:31''s *all the holy angels with him* walks, in continuity with Deuteronomy 33:2 + Daniel 7:10 + Zechariah 14:5 + Jude 14-15; 1 Enoch 62:9 names THE direct verbal-anchor for the Son-of-Adam-raising-up-the-kings-and-mighty-from-their-thrones substance (*Shall raise up the kings and the mighty from their seats, And the strong from their thrones*) — the reversal-architecture the sheep-and-goats-judgment walks-out, in continuity with Tehillim (Psalm) 2:9 + Tehillim (Psalm) 110:5-6 + Isaiah 24:21; 1 Enoch 62:11 names the humbling-of-the-strong + the abasing-of-the-pride-of-the-mighty substance + the darkness-as-dwelling architecture — the substantial-outer-darkness-substance of Matt 25:30, 22:13, and the everlasting-fire-substance of Matt 25:41; 1 Enoch 63:7 names the kings-and-mighty-seized-with-great-terror + the prayer-and-supplication-too-late substance — the substantial-substance the goats walk-into at the substantial *Lord, when saw we thee* of Matt 25:44, with the substantial-recognition-coming-too-late and the substantial-cutoff-being-substantial. The framework reads the cluster carefully — this thread sits parallel to the S154 thread `the-son-of-adam-glorified-in-1-enoch-throne-vision-and-parables` (anchored on Matt 17 transfiguration) which carried the glorified-form-substance for the pre-resurrection-foretaste; this thread carries the judgment-of-the-kings-and-mighty-cast-down + reversal architecture for the second-coming + the sheep-and-goats-judgment-at-the-throne-of-his-glory. The substantial-everlasting-fire of v.41 was-substantively-prepared-FOR-the-devil-and-his-angels per Jude 6-7 + 2 Peter 2:4 + Revelation 20:10 + 20:14-15, NOT for the surviving-nations categorically; the substantial-surviving-nations-and-the-kings-and-mighty-who-possess-the-earth (1 Enoch 63:7) align-themselves-into-the-Watcher-architecture by their reception-or-rejection of the King''s-brethren during the tribulation per Red Line #11; the substantial-Universalist-substance is explicitly-ruled-out — the substantial-cutoff at the substantial-shut-door + the substantial-everlasting-punishment of v.46 is substantial.',
       sv.verse_id, ev.verse_id, 'complete_study', 351
  FROM _s156_xref_lookup sv, _s156_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 25 AND sv.verse_number = 31
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 25 AND ev.verse_number = 41
ON CONFLICT (slug) DO NOTHING;

