-- ---------------------------------------------------------------------
-- Verification block.
-- ---------------------------------------------------------------------
DO $verify$
DECLARE
  v_xref_inserted INT;
  v_thread_inserted INT;
  v_member_inserted INT;
BEGIN
  SELECT count(*) INTO v_xref_inserted FROM cross_references x
    JOIN _s156_xref_lookup sv ON sv.verse_id = x.source_verse_id
   WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 25
     AND x.tier_required = 'extras' AND x.source = 'manual';

  SELECT count(*) INTO v_thread_inserted FROM cross_reference_threads
   WHERE slug IN (
     'the-day-of-vindication-of-the-righteous-and-the-judgment-of-the-nations-in-wisdom-of-solomon',
     'the-diligent-stewardship-versus-the-slothful-servant-in-sirach',
     'the-few-saved-many-lost-and-the-post-harvest-sifting-in-2-esdras',
     'the-mercy-toward-the-poor-the-stranger-and-the-needy-as-the-criterion-of-righteousness-in-sirach-and-tobit',
     'the-judgment-of-the-kings-and-the-mighty-cast-down-in-1-enoch-parables'
   );

  SELECT count(*) INTO v_member_inserted
    FROM cross_reference_thread_members m
    JOIN cross_reference_threads t ON t.id = m.thread_id
   WHERE t.slug IN (
     'the-day-of-vindication-of-the-righteous-and-the-judgment-of-the-nations-in-wisdom-of-solomon',
     'the-diligent-stewardship-versus-the-slothful-servant-in-sirach',
     'the-few-saved-many-lost-and-the-post-harvest-sifting-in-2-esdras',
     'the-mercy-toward-the-poor-the-stranger-and-the-needy-as-the-criterion-of-righteousness-in-sirach-and-tobit',
     'the-judgment-of-the-kings-and-the-mighty-cast-down-in-1-enoch-parables'
   );

  RAISE NOTICE 'S156 Matt 25 verify: extras xrefs from canon/matthew/25 = %, threads = %, members = %',
    v_xref_inserted, v_thread_inserted, v_member_inserted;

  IF v_thread_inserted <> 5 THEN
    RAISE EXCEPTION 'Expected 5 threads inserted; got %', v_thread_inserted;
  END IF;
  IF v_xref_inserted < 22 THEN
    RAISE EXCEPTION 'Expected at least 22 Matt-25 extras xrefs; got %', v_xref_inserted;
  END IF;
  IF v_member_inserted < 22 THEN
    RAISE EXCEPTION 'Expected at least 22 thread members; got %', v_member_inserted;
  END IF;
END;
$verify$;

COMMIT;
